// One Slack message listing the new ads, grouped by competitor. No new ad: no message.
const ads = $input.all().map((i) => i.json).filter((a) => a.found !== false);
if (ads.length === 0) return [];
const byCompetitor = {};
for (const a of ads) (byCompetitor[a.query] ??= []).push(a);
const day = (iso) => (iso ? iso.slice(0, 10) : 'n/a');
const blocks = Object.entries(byCompetitor).map(([competitor, list]) => {
  const lines = list.slice(0, 10).map((a) => `• ${a.format ?? 'ad'} by ${a.advertiserName ?? 'unknown advertiser'}, first shown ${day(a.firstShown)}: <${a.transparencyUrl}|view ad>`);
  if (list.length > 10) lines.push(`…and ${list.length - 10} more`);
  return `*${competitor}*: ${list.length} new ad${list.length > 1 ? 's' : ''}\n${lines.join('\n')}`;
});
const text = `:mega: *New competitor Google ads* (${ads[0].region})\n\n${blocks.join('\n\n')}`;
return [{ json: { text, newAds: ads.length } }];
